const fs = require('fs');
const path = require('path');

async function createAndSetPermissions() {
    const testDir = './testdir';
    const testFile = 'testfile.txt';

    // Create directory with 700 permissions
    await fs.promises.mkdir(testDir, { mode: 0o700 });

    // Write file with 600 permissions
    await fs.promises.writeFile(
        path.join(testDir, testFile),
        'sensitive content',
        { mode: 0o600 }
    );

    // Verify directory and file permissions
    const stats = await fs.promises.stat(testDir);
    console.log(`Directory permissions: ${stats.mode & 0o777}`);

    const fileStats = await fs.promises.stat(path.join(testDir, testFile));
    console.log(`File permissions: ${fileStats.mode & 0o777}`);
}

createAndSetPermissions().catch(console.error);
